// ─── Community Posts ──────────────────────────────────────────────────────────

export interface CommunityPostWithRepost extends CommunityPost {
  repostOf: CommunityPost | null;
}

// External reference data resolved at query time (artwork or blog repost)
export interface ResolvedExternalReference {
  type:   'artwork' | 'blog';
  id:     string;
  title:  string;
  image:  string | null;
  slug:   string;
  excerpt?: string;
}

export async function getCommunityPosts(
  opts: {
    take?:       number;
    skip?:       number;
    authorId?:   string;
    search?:     string;   // partial match on authorName
    sort?:       'latest' | 'oldest' | 'popular';
  } = {}
): Promise<CommunityPostWithRepost[]> {
  const { take = 20, skip = 0, authorId, search, sort = 'latest' } = opts;

  const orderBy =
    sort === 'popular'
      ? [{ likesCount: 'desc' as const }, { commentsCount: 'desc' as const }]
      : sort === 'oldest'
      ? [{ createdAt: 'asc' as const }]
      : [{ createdAt: 'desc' as const }];

  try {
    const posts = await prisma.communityPost.findMany({
      where: {
        status: 'published',
        ...(authorId ? { authorId } : {}),
        ...(search
          ? { authorName: { contains: search, mode: 'insensitive' } }
          : {}),
      },
      orderBy,
      take,
      skip,
      include: { repostOf: true },
    }) as CommunityPostWithRepost[];
    return posts.map(sanitizePostContent);
  } catch {
    return [];
  }
}

/**
 * Fetch one post by slug (new posts) or ID (old posts / direct links).
 */
export async function getCommunityPost(
  slugOrId: string
): Promise<CommunityPostWithRepost | null> {
  try {
    const bySlug = await prisma.communityPost.findFirst({
      where:   { slug: slugOrId, status: 'published' },
      include: { repostOf: true },
    });
    if (bySlug) return sanitizePostContent(bySlug as CommunityPostWithRepost);

    const byId = await prisma.communityPost.findUnique({
      where:   { id: slugOrId },
      include: { repostOf: true },
    }) as CommunityPostWithRepost | null;
    return sanitizePostContent(byId);
  } catch {
    return null;
  }
}

export async function createCommunityPost(data: {
  authorId:     string;
  authorName:   string;
  authorImage?: string;
  content:      string;
  imageUrl?:    string;
  imageId?:     string;
}): Promise<CommunityPost> {
  const slug = generateCommunitySlug(data.content);
  return prisma.communityPost.create({
    data: {
      slug,
      authorId:    data.authorId,
      authorName:  data.authorName,
      authorImage: data.authorImage ?? null,
      // SECURITY: post content is rendered with dangerouslySetInnerHTML, and any
      // signed-in user can author it. Sanitize against a strict allowlist before
      // it ever reaches the database. See lib/html-sanitizer.ts.
      content:     sanitizeRichHtml(data.content),
      imageUrl:    data.imageUrl ?? null,
      imageId:     data.imageId  ?? null,
      status:      'published',
    },
  });
}

/**
 * Sanitize the rich-text fields of a post loaded from the database.
 *
 * Defence in depth: rows created before HTML sanitization shipped may still
 * contain hostile markup, so we scrub on read as well as on write rather than
 * running a destructive data migration.
 */
function sanitizePostContent<T extends CommunityPost | null>(post: T): T {
  if (!post) return post;
  const cleaned = { ...post, content: sanitizeRichHtml(post.content) } as T & CommunityPost;
  const nested  = (cleaned as unknown as CommunityPostWithRepost).repostOf;
  if (nested) {
    (cleaned as unknown as CommunityPostWithRepost).repostOf = {
      ...nested,
      content: sanitizeRichHtml(nested.content),
    };
  }
  return cleaned;
}

/**
 * Create a repost of an external content item (artwork or blog post).
 * The reference metadata is cached on the post row for fast feed rendering.
 */
export async function createExternalRepost(data: {
  authorId:       string;
  authorName:     string;
  authorImage?:   string;
  note:           string;
  referenceType:  'artwork' | 'blog';
  referenceId:    string;
  referenceTitle: string;
  referenceImage: string | null;
  referenceSlug:  string;
}): Promise<CommunityPost> {
  const slug = generateCommunitySlug(data.note || `repost-${data.referenceType}-${data.referenceId}`);
  return prisma.communityPost.create({
    data: {
      slug,
      authorId:       data.authorId,
      authorName:     data.authorName,
      authorImage:    data.authorImage  ?? null,
      content:        sanitizeRichHtml(data.note, 1000),
      referenceType:  data.referenceType,
      referenceId:    data.referenceId,
      referenceTitle: data.referenceTitle,
      referenceImage: data.referenceImage ?? null,
      referenceSlug:  data.referenceSlug,
      status:         'published',
    },
  });
}

export async function createRepost(data: {
  authorId:     string;
  authorName:   string;
  authorImage?: string;
  repostNote:   string;
  repostOfId:   string;
}): Promise<CommunityPost> {
  // Verify the target exists before creating the repost, otherwise the
  // transaction fails on the counter update and the caller sees a bare 500.
  const target = await prisma.communityPost.findUnique({
    where:  { id: data.repostOfId },
    select: { id: true, status: true },
  });
  if (!target || target.status !== 'published') {
    throw new Error('Post not found');
  }

  const slug   = generateCommunitySlug(data.repostNote || `repost-${data.repostOfId}`);
  const [post] = await prisma.$transaction([
    prisma.communityPost.create({
      data: {
        slug,
        authorId:      data.authorId,
        authorName:    data.authorName,
        authorImage:   data.authorImage ?? null,
        content:       sanitizeRichHtml(data.repostNote, 1000),
        repostOfId:    data.repostOfId,
        repostNote:    sanitizeRichHtml(data.repostNote, 1000),
        referenceType: 'post',
        referenceId:   data.repostOfId,
        status:        'published',
      },
    }),
    prisma.communityPost.update({
      where: { id: data.repostOfId },
      data:  { repostsCount: { increment: 1 } },
    }),
  ]);
  return post;
}

export async function incrementShareCount(postId: string): Promise<void> {
  try {
    await prisma.communityPost.update({
      where: { id: postId },
      data:  { shareCount: { increment: 1 } },
    });
  } catch { /* non-critical */ }
}

export async function deleteCommunityPost(
  id: string,
  userId: string,
  opts: { asAdmin?: boolean } = {},
): Promise<void> {
  const post = await prisma.communityPost.findUnique({ where: { id } });
  // Distinguish "missing" from "not yours" so the route can return 404 vs 403
  // instead of collapsing both into a generic failure.
  if (!post) {
    throw new Error('Post not found');
  }
  if (!opts.asAdmin && post.authorId !== userId) {
    throw new Error('Forbidden: you can only delete your own posts');
  }
  await prisma.communityPost.delete({ where: { id } });
}

// ─── Community Likes ──────────────────────────────────────────────────────────

export async function getCommunityLikeCount(postId: string): Promise<number> {
  try {
    return await prisma.communityLike.count({ where: { postId } });
  } catch {
    return 0;
  }
}

export async function hasCommunityLiked(
  postId: string,
  userId: string
): Promise<boolean> {
  try {
    const like = await prisma.communityLike.findUnique({
      where: { postId_userId: { postId, userId } },
    });
    return !!like;
  } catch {
    return false;
  }
}

export async function toggleCommunityLike(
  postId: string,
  userId: string
): Promise<{ liked: boolean; count: number }> {
  const existing = await prisma.communityLike.findUnique({
    where: { postId_userId: { postId, userId } },
  });

  if (existing) {
    await prisma.communityLike.delete({
      where: { postId_userId: { postId, userId } },
    });
    await prisma.communityPost.update({
      where: { id: postId },
      data:  { likesCount: { decrement: 1 } },
    }).catch(() => { /* floor at 0 */ });
  } else {
    await prisma.communityLike.create({ data: { postId, userId } });
    await prisma.communityPost.update({
      where: { id: postId },
      data:  { likesCount: { increment: 1 } },
    });
  }

  const count = await getCommunityLikeCount(postId);
  return { liked: !existing, count };
}

// ─── Static Pages ─────────────────────────────────────────────────────────────

export async function getStaticPage(
  slug: StaticPageSlug
): Promise<StaticPage | null> {
  try {
    return await prisma.staticPage.findUnique({ where: { id: slug } });
  } catch {
    return null;
  }
}

export async function upsertStaticPage(
  slug: StaticPageSlug,
  data: { title: string; content: string }
): Promise<StaticPage> {
  const content = sanitizeRichHtml(data.content);
  return prisma.staticPage.upsert({
    where:  { id: slug },
    update: { title: data.title, content },
    create: { id: slug, title: data.title, content },
  });
}

// ─── Social Accounts (public display) ────────────────────────────────────────

export interface PublicSocialAccount {
  id:              string;
  platform:        'INSTAGRAM' | 'YOUTUBE' | 'TWITTER' | 'FACEBOOK';
  username:        string;
  // Identity
  displayName:     string | null;
  avatarUrl:       string | null;
  // Enriched profile fields
  bio:             string | null;
  category:        string | null;
  externalUrl:     string | null;
  profileUrl:      string | null;
  // Counts
  followers:       number | null;
  following:       number | null;
  posts:           number | null;
  // Manual override
  manualFollowers: number | null;
  manualPosts:     number | null;
  useManual:       boolean;
  // Meta
  oauthConnected:  boolean;
  lastFetchMethod: string | null;
  fetchStatus:     string;
  lastFetchedAt:   Date | null;
}

/**
 * Returns all social accounts that have at least some data to display.
 * Ordered by platform so the display order is consistent.
 * Used on /about and / pages (server-side, zero client API calls).
 */
export async function getPublicSocialAccounts(): Promise<PublicSocialAccount[]> {
  try {
    const accounts = await prisma.socialAccount.findMany({
      where:   { profileId: 'artist_profile' },
      orderBy: { createdAt: 'asc' },
      select: {
        id:              true,
        platform:        true,
        username:        true,
        displayName:     true,
        avatarUrl:       true,
        bio:             true,
        category:        true,
        externalUrl:     true,
        profileUrl:      true,
        followers:       true,
        following:       true,
        posts:           true,
        manualFollowers: true,
        manualPosts:     true,
        useManual:       true,
        oauthConnected:  true,
        lastFetchMethod: true,
        fetchStatus:     true,
        lastFetchedAt:   true,
      },
    });
    // Only return accounts that have something to show (followers or manual)
    return accounts.filter(a => {
      const f = a.useManual ? a.manualFollowers : a.followers;
      return f !== null && f > 0;
    }) as PublicSocialAccount[];
  } catch {
    return [];
  }
}
